<template><article class="card repair-card"><div><h3>{{repair.title}}</h3><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · {{new Date(repair.created_at).toLocaleString()}}</small><p v-if="repair.rework_count>0" class="rework">返工次数：{{repair.rework_count}}</p><p v-if="repair.reject_reason" class="reject-reason">退回原因：{{repair.reject_reason}}</p></div><div class="repair-side"><RepairStatusBadge :status="repair.status"/><div v-if="canAccept" class="repair-actions"><el-button size="small" type="success" @click="emit('confirm',repair.id)">确认验收</el-button><el-button size="small" type="danger" plain @click="emit('reject',repair.id)">退回</el-button></div></div></article></template><script setup lang="ts">import{computed}from'vue';import type{Repair}from'../../types';import{authStore}from'../../stores/authStore';import RepairStatusBadge from'./RepairStatusBadge.vue';const p=defineProps<{repair:Repair}>();const emit=defineEmits<{confirm:[id:number];reject:[id:number]}>();const canAccept=computed(()=>p.repair.status==='done'&&authStore.user?.id===p.repair.user_id)</script>
